// {"P5LIVE":{"name":"control_room"}}
// ============================================================
// CONTROL ROOM — instrumento visual con sliders y teclado
// ------------------------------------------------------------
// SLIDERS (esquina superior izquierda):
//   • cols      → densidad de la grilla    (4 — 40)
//   • shake     → temblor aleatorio        (0 — 60)
//   • pulse     → velocidad del latido     (0 — 10)
//   • thick     → grosor de línea          (0.5 — 8)
//   • trail     → estela / motion blur     (0 — 255)
//   • twist     → rotación global          (0 — 360)
//
// TECLADO:
//   1 / 2 / 3 / 4 → paleta de colores
//   f             → toggle relleno (fill on/off)
//   s             → toggle figura (cuadrado / círculo)
//   r             → reset sliders a valores por defecto
//   h             → mostrar / ocultar HUD
//   espacio       → flash blanco (drop!)
// ============================================================

let sCols, sShake, sPulse, sThick, sTrail, sTwist
let palette = 1
let useFill = false
let useCircle = false
let showHUD = true
let flash = 0

// 4 paletas pensadas para algorave
const PALETTES = [
	[[255, 255, 255], [200, 200, 200]],            // 1: monocromo
	[[255, 60, 120], [60, 200, 255], [255, 220, 0]], // 2: neón
	[[255, 80, 0], [120, 0, 255], [0, 255, 180]],   // 3: caliente/frío
	[[40, 255, 40], [0, 100, 0], [200, 255, 200]]   // 4: matrix verde
]

function setup() {
	createCanvas(windowWidth, windowHeight)
	rectMode(CENTER)
	angleMode(DEGREES)
	buildSliders()
	background(0)
}

// crea los sliders HTML y los posiciona en columna
function buildSliders() {
	let y = 20
	const step = 38
	sCols  = labeledSlider("cols",   4,   40,  12,  1,    20, y);            y += step
	sShake = labeledSlider("shake",  0,   60,  6,   1,    20, y);            y += step
	sPulse = labeledSlider("pulse",  0,   10,  3,   0.1,  20, y);            y += step
	sThick = labeledSlider("thick",  0.5, 8,   1.5, 0.1,  20, y);            y += step
	sTrail = labeledSlider("trail",  0,   255, 255, 1,    20, y);            y += step
	sTwist = labeledSlider("twist",  0,   360, 0,   1,    20, y)
}

// helper: crea un slider con etiqueta y lo posiciona
function labeledSlider(name, mn, mx, val, stepv, x, y) {
	let s = createSlider(mn, mx, val, stepv)
	s.position(x, y)
	s.style("width", "160px")
	s.elt.dataset.label = name   // guardamos el nombre para el HUD
	return s
}

function draw() {
	// fondo translúcido = estela; trail=255 limpia totalmente
	noStroke()
	fill(0, sTrail.value())
	rect(width/2, height/2, width, height)

	// flash blanco (tecla espacio)
	if (flash > 0) {
		fill(255, flash)
		rect(width/2, height/2, width, height)
		flash -= 15
	}

	// rotación global controlada por "twist"
	push()
	translate(width/2, height/2)
	rotate(sTwist.value())
	translate(-width/2, -height/2)

	pulseGrid(
		sCols.value(),
		sShake.value(),
		sPulse.value(),
		sThick.value()
	)
	pop()

	if (showHUD) drawHUD()
}

// grilla que tiembla y respira a la vez
// cols → cantidad de columnas
// shake → intensidad del temblor aleatorio
// pulse → velocidad del latido (con sin)
// thick → grosor de línea
function pulseGrid(cols, shake, pulse, thick) {
	let step = width / cols
	// el "latido" modula el tamaño de cada celda
	let beat = 0.5 + 0.5 * sin(frameCount * pulse)
	let cellSize = step * (0.4 + 0.5 * beat)
	strokeWeight(thick)

	for (let x = step/2; x < width; x += step) {
		for (let y = step/2; y < height; y += step) {
			let c = pickColor(x, y)
			stroke(c[0], c[1], c[2])
			if (useFill) fill(c[0], c[1], c[2], 80); else noFill()
			let ox = random(-shake, shake)
			let oy = random(-shake, shake)
			if (useCircle) circle(x + ox, y + oy, cellSize)
			else            square(x + ox, y + oy, cellSize)
		}
	}
}

// elige color de la paleta actual según posición (alterna celdas)
function pickColor(x, y) {
	let pal = PALETTES[palette - 1]
	let idx = (floor(x / 50) + floor(y / 50)) % pal.length
	return pal[idx]
}

// HUD: muestra valores actuales arriba a la derecha
function drawHUD() {
	push()
	resetMatrix()
	noStroke()
	fill(0, 180)
	rect(width - 110, 100, 200, 200)
	fill(255)
	textFont("monospace")
	textSize(12)
	textAlign(LEFT, TOP)
	let info = [
		"palette " + palette,
		"fill    " + (useFill ? "on" : "off"),
		"shape   " + (useCircle ? "circle" : "square"),
		"",
		"1-4 paleta   f fill",
		"s shape      r reset",
		"h hud        space flash"
	]
	text(info.join("\n"), width - 200, 20)
	pop()
}

function keyPressed() {
	if (key >= "1" && key <= "4") palette = int(key)
	if (key === "f" || key === "F") useFill = !useFill
	if (key === "s" || key === "S") useCircle = !useCircle
	if (key === "h" || key === "H") showHUD = !showHUD
	if (key === "r" || key === "R") resetSliders()
	if (key === " ") flash = 255
}

// vuelve los sliders a sus valores por defecto
function resetSliders() {
	sCols.value(12); sShake.value(6); sPulse.value(3)
	sThick.value(1.5); sTrail.value(255); sTwist.value(0)
}

