function organicShape(x, y, w, h) {

  beginShape()

  for (let a = 0; a < TWO_PI; a += 0.4) {

    let r1 = w * 0.5 + random(-20, 20)
    let r2 = h * 0.5 + random(-20, 20)

    let px = cos(a) * r1
    let py = sin(a) * r2

    vertex(px, py)
  }

  endShape(CLOSE)
}

