function draw() {
  background(5, 5, 15, 30)

  translate(width / 2, height / 2)

  let portalSize = map(mouseX, 0, width, 80, 350)
  let gravity = map(mouseY, 0, height, 0.5, 3)

  for (let i = 0; i < particles.length; i++) {
    let p = particles[i]

    p.angle += p.speed * gravity

    let wave = sin(frameCount * 0.04 + p.radius * 0.03) * 30
    let x = cos(p.angle) * (p.radius + wave)
    let y = sin(p.angle) * (p.radius + wave)

    let distanceGlow = map(p.radius, 40, 300, 255, 50)

    fill(0, 200, 255, distanceGlow)
    ellipse(x, y, p.size)

    fill(255, 0, 180, distanceGlow / 2)
    ellipse(x * 0.97, y * 0.97, p.size * 1.8)
  }

  noFill()
  stroke(0, 255, 255, 180)
  strokeWeight(3)
  ellipse(0, 0, portalSize)

  stroke(255, 0, 180, 120)
  ellipse(0, 0, portalSize + sin(frameCount * 0.08) * 40)
}

